<?php

namespace App\Support;

/**
 * Whether a storage key is safe to serve.
 *
 * Storage keys are generated by the app, never taken from user
 * input, but a key read back from the database is still treated
 * as untrusted: a key that escapes its prefix (with `..`, an
 * absolute path, or a backslash) must never be handed to the
 * filesystem. Download and preview endpoints check every key
 * through here before touching storage.
 */
class StorageKey
{
    /**
     * Whether the key stays inside its prefix directory.
     */
    public static function isSafe(string $key, string $prefix): bool
    {
        if ($key === '' || str_contains($key, "\0") || str_contains($key, '\\')) {
            return false;
        }

        if (! str_starts_with($key, $prefix.'/')) {
            return false;
        }

        foreach (explode('/', $key) as $segment) {
            if ($segment === '' || $segment === '.' || $segment === '..') {
                return false;
            }
        }

        return true;
    }
}
